from lib import *
L = lambda *a, **k: lesson(5, "A0", *a, **k)
N = "number"
L(1, "Від 11 до 15", "Назвати й розпізнати числа від одинадцяти до п'ятнадцяти.",
 "Eleven і twelve треба просто запам'ятати. Далі числа закінчуються на -teen: thirteen, fourteen, fifteen. Наголос у них падає на -teen.",
 [W("number", "/ˈnʌmbə/", "noun", "число, номер", "What number is it?", "Яке це число?"),
  W("eleven", "/ɪˈlevn/", N, "одинадцять", "I have eleven books.", "У мене одинадцять книжок."),
  W("twelve", "/twelv/", N, "дванадцять", "He's twelve.", "Йому дванадцять."),
  W("thirteen", "/ˌθɜːˈtiːn/", N, "тринадцять", "She's thirteen.", "Їй тринадцять."),
  W("fourteen", "/ˌfɔːˈtiːn/", N, "чотирнадцять", "It's fourteen pounds.", "Це коштує чотирнадцять фунтів."),
  W("fifteen", "/ˌfɪfˈtiːn/", N, "п'ятнадцять", "My son is fifteen.", "Моєму синові п'ятнадцять.")],
 [fb("The phone is new ___ very expensive.", ["but", "very", "many"], "But — «але».", "Повторимо. Оберіть слово, якого бракує"),
  mt([("eleven", "11"), ("twelve", "12"), ("thirteen", "13"), ("fourteen", "14"), ("fifteen", "15")], "Eleven і twelve — винятки, далі додається -teen.", "З'єднайте слово з числом"),
  liu("twelve", "Прослухайте. Яке це число?", ["12", "11", "20"], "Twelve — дванадцять. Twenty — двадцять."),
  liu("fifteen", "Прослухайте. Яке це число?", ["15", "50", "5"], "Fifteen — 15: наголос на кінці. Fifty — 50: наголос на початку."),
  fb("ten, eleven, ___, thirteen", ["twelve", "fourteen", "twenty"], "Після eleven (11) іде twelve (12).", "Яке число пропущене?"),
  mc("Скільки буде ten + four?", ["fourteen", "forty", "thirteen"], "10 + 4 = 14 — fourteen. Forty — це 40."),
  mc("Як правильно написати число 15?", ["fifteen", "fiveteen", "fiften"], "Fifteen: five змінюється на fif-."),
  liu("My daughter is thirteen years old.", "Прослухайте. Скільки років доньці?", ["13", "30", "3"], "Thirteen — 13. Thirty — 30."),
  tr("одинадцять", ["eleven"], "Eleven — одинадцять."),
  li("How old is your son?", "Вашому синові дванадцять. Що відповісти?", ["He's twelve.", "He's twenty.", "She's twelve."], "Про сина — he: He's twelve.")])
L(2, "Від 16 до 19 і нуль", "Назвати числа до дев'ятнадцяти й не плутати 13 з 30.",
 "Sixteen, seventeen, eighteen, nineteen будуються однаково: число + teen. Головна пастка — на слух: thirTEEN (13) і THIRty (30). У -teen наголос на кінці й довге «і».",
 [W("sixteen", "/ˌsɪksˈtiːn/", N, "шістнадцять", "She's sixteen.", "Їй шістнадцять."),
  W("seventeen", "/ˌsevnˈtiːn/", N, "сімнадцять", "It's seventeen euros.", "Це коштує сімнадцять євро."),
  W("eighteen", "/ˌeɪˈtiːn/", N, "вісімнадцять", "He's eighteen.", "Йому вісімнадцять."),
  W("nineteen", "/ˌnaɪnˈtiːn/", N, "дев'ятнадцять", "I'm nineteen.", "Мені дев'ятнадцять."),
  W("zero", "/ˈzɪərəʊ/", N, "нуль", "Zero, one, two.", "Нуль, один, два.")],
 [liu("fourteen", "Повторимо. Прослухайте. Яке це число?", ["14", "40", "4"], "Fourteen — 14."),
  mt([("sixteen", "16"), ("seventeen", "17"), ("eighteen", "18"), ("nineteen", "19"), ("zero", "0")], "Число + teen. В eighteen одна літера t.", "З'єднайте слово з числом"),
  liu("thirty", "Прослухайте уважно. Яке це число?", ["30", "13", "3"], "THIRty — наголос на початку, це 30."),
  liu("sixteen", "Прослухайте уважно. Яке це число?", ["16", "60", "6"], "sixTEEN — наголос на кінці, це 16."),
  fb("sixteen, seventeen, ___, nineteen", ["eighteen", "eleven", "eighty"], "16, 17, 18, 19.", "Яке число пропущене?"),
  mc("Скільки буде ten + nine?", ["nineteen", "ninety", "eighteen"], "10 + 9 = 19 — nineteen."),
  mc("Яке число найбільше?", ["forty", "fourteen", "nineteen"], "Forty — 40. Fourteen — 14, nineteen — 19."),
  liu("It's seventeen pounds.", "Прослухайте. Скільки це коштує?", ["17 фунтів", "70 фунтів", "7 фунтів"], "Seventeen — 17."),
  tr("вісімнадцять", ["eighteen"], "Eighteen — вісімнадцять."),
  li("How old are you?", "Вам дев'ятнадцять. Що відповісти?", ["I'm nineteen.", "I'm ninety.", "I have nineteen."], "I'm nineteen.")])
L(3, "Десятки до ста", "Назвати десятки від двадцяти до ста.",
 "Десятки закінчуються на -ty: sixty, seventy, eighty, ninety. Наголос у них на початку слова. Сто — a hundred або one hundred.",
 [W("sixty", "/ˈsɪksti/", N, "шістдесят", "My mother is sixty.", "Моїй мамі шістдесят."),
  W("seventy", "/ˈsevnti/", N, "сімдесят", "It's seventy pounds.", "Це коштує сімдесят фунтів."),
  W("eighty", "/ˈeɪti/", N, "вісімдесят", "He's eighty.", "Йому вісімдесят."),
  W("ninety", "/ˈnaɪnti/", N, "дев'яносто", "It's ninety euros.", "Це коштує дев'яносто євро."),
  W("hundred", "/ˈhʌndrəd/", N, "сто", "It's a hundred pounds.", "Це коштує сто фунтів.")],
 [liu("nineteen", "Повторимо. Прослухайте. Яке це число?", ["19", "90", "9"], "nineTEEN — 19."),
  mt([("sixty", "60"), ("seventy", "70"), ("eighty", "80"), ("ninety", "90"), ("hundred", "100")], "Десятки на -ty і сто.", "З'єднайте слово з числом"),
  mt([("twenty", "20"), ("thirty", "30"), ("forty", "40"), ("fifty", "50")], "Ці десятки ви вже знаєте.", "З'єднайте слово з числом"),
  liu("eighty", "Прослухайте. Яке це число?", ["80", "18", "8"], "EIGHty — 80."),
  fb("seventy, eighty, ___, a hundred", ["ninety", "nineteen", "sixty"], "70, 80, 90, 100.", "Яке число пропущене?"),
  mc("Скільки буде fifty + fifty?", ["a hundred", "fifteen", "ninety"], "50 + 50 = 100 — a hundred."),
  mc("Як правильно написати число 40?", ["forty", "fourty", "fourteen"], "Forty пишеться без u, хоча four — з u."),
  liu("It's sixty euros.", "Прослухайте. Скільки це коштує?", ["60 євро", "16 євро", "70 євро"], "Sixty — 60."),
  tr("сто", ["a hundred", "one hundred", "hundred"], "A hundred або one hundred."),
  li("How much is the ticket?", "Квиток коштує 90 фунтів. Що відповість касир?", ["It's ninety pounds.", "It's nineteen pounds.", "It's nine pounds."], "Ninety — 90.")])
L(4, "Двадцять один, тридцять п'ять", "Скласти будь-яке число до ста й зрозуміти ціну.",
 "Складене число — це десяток і одиниця через дефіс: twenty-one, thirty-five, ninety-nine. Ціну з копійками читають двома числами: £4.50 — four fifty.",
 [W("price", "/praɪs/", "noun", "ціна", "What's the price?", "Яка ціна?"),
  W("cent", "/sent/", "noun", "цент", "It's fifty cents.", "Це коштує п'ятдесят центів."),
  W("change", "/tʃeɪndʒ/", "noun", "решта", "Here's your change.", "Ось ваша решта.")],
 [mc("Повторимо. Скільки буде thirty + thirty?", ["sixty", "sixteen", "thirteen"], "30 + 30 = 60 — sixty."),
  mcu("Яке це число: twenty-one?", ["21", "12", "20"], "Twenty — 20, one — 1: разом 21."),
  mcu("Яке це число: forty-seven?", ["47", "74", "14"], "Forty — 40, seven — 7."),
  liu("thirty-five", "Прослухайте. Яке це число?", ["35", "53", "25"], "Thirty-five — 35."),
  liu("ninety-nine", "Прослухайте. Яке це число?", ["99", "19", "90"], "Ninety-nine — 99."),
  mc("Як сказати 68?", ["sixty-eight", "eighty-six", "sixteen-eight"], "Спочатку десяток: sixty, потім eight."),
  mt([("price", "ціна"), ("change", "решта"), ("cent", "цент"), ("bill", "рахунок")], "Слова, які чути біля каси."),
  liu("It's four fifty.", "Прослухайте ціну. Скільки це коштує?", ["4,50", "45", "4,15"], "Four fifty — чотири і п'ятдесят: 4,50."),
  tr("двадцять два", ["twenty-two", "twenty two"], "Twenty-two — через дефіс."),
  li("That's twelve pounds. — Here's twenty.", "Ви дали двадцять, а треба дванадцять. Що скаже касир?", ["Here's your change.", "Here's your menu.", "That's all."], "Change — решта.")])
L(5, "Мій номер телефону", "Назвати номер телефону, адресу й електронну пошту.",
 "Номер телефону читають по одній цифрі. Нуль у номері часто називають «оу» (oh). В адресі пошти @ читається at, а крапка — dot.",
 [W("phone number", "/ˈfəʊn ˌnʌmbə/", "noun", "номер телефону", "What's your phone number?", "Який ваш номер телефону?"),
  W("address", "/əˈdres/", "noun", "адреса", "What's your address?", "Яка ваша адреса?"),
  W("street", "/striːt/", "noun", "вулиця", "I live in Green Street.", "Я живу на вулиці Грін."),
  W("email", "/ˈiːmeɪl/", "noun", "електронна пошта", "What's your email?", "Яка ваша електронна пошта?"),
  W("at", "/æt/", "preposition", "знак @ в адресі пошти", "anna at mail dot com", "anna@mail.com"),
  W("dot", "/dɒt/", "noun", "крапка (в адресі)", "mail dot com", "mail.com")],
 [liu("forty-two", "Повторимо. Прослухайте. Яке це число?", ["42", "24", "14"], "Forty-two — 42."),
  mt([("phone number", "номер телефону"), ("address", "адреса"), ("street", "вулиця"), ("email", "електронна пошта")], "Те, що питають в анкеті чи готелі."),
  liu("What's your phone number?", "Прослухайте. Що вас питають?", ["Номер телефону", "Адресу", "Ім'я"], "Phone number — номер телефону."),
  liu("five, zero, seven, three, one", "Прослухайте номер", ["5 0 7 3 1", "5 0 7 1 3", "5 7 0 3 1"], "Номер називають по одній цифрі."),
  mcu("Як прочитати anna@mail.com?", ["anna at mail dot com", "anna in mail dot com", "anna and mail com"], "@ — at, крапка — dot."),
  fb("What's ___ address?", ["your", "you", "I"], "«Ваша адреса» — your address."),
  fb("I live ___ London.", ["in", "dot", "your"], "У місті — in: I live in London."),
  bs("Який ваш номер телефону?", ["What's", "your", "phone", "number"], ["address", "is"], "What's your phone number?"),
  tr("Яка ваша адреса?", ["What's your address", "What is your address"], "What's your address?"),
  li("What's your email?", "Вас питають про пошту. Що відповісти?", ["It's anna at mail dot com.", "It's five pounds.", "I'm from Ukraine."], "Адресу пошти називають через at і dot.")])
L(6, "Повторення: числа в житті", "Впевнено розуміти вік, ціни й номери.",
 "Нових слів немає. Числа трапляються всюди: вік, ціна, номер телефону. Тренуємо їх на слух і в розмові.",
 [],
 [liu("seventy-three", "Прослухайте. Яке це число?", ["73", "37", "13"], "Seventy-three — 73."),
  liu("fourteen", "Прослухайте уважно. Яке це число?", ["14", "40", "44"], "fourTEEN — 14."),
  mc("Як сказати 86?", ["eighty-six", "sixty-eight", "eighteen-six"], "Eighty — 80, six — 6."),
  tr("п'ятдесят п'ять", ["fifty-five", "fifty five"], "Fifty-five."),
  liu("My father is sixty-two.", "Прослухайте. Скільки років татові?", ["62", "26", "72"], "Sixty-two — 62."),
  li("How much is it?", "Це коштує 15 фунтів. Що відповість продавець?", ["It's fifteen pounds.", "It's fifty pounds.", "It's five pounds."], "Fifteen — 15."),
  fb("Here's your ___. Thank you!", ["change", "price", "number"], "Change — решта."),
  bs("Який ваш номер телефону?", ["What's", "your", "phone", "number"], ["email", "my"], "What's your phone number?"),
  mcu("Яке число тут: a hundred?", ["100", "1000", "10"], "A hundred — сто."),
  li("What's your address?", "Що відповісти?", ["Twelve Green Street.", "Twelve years old.", "Twelve pounds."], "Адресу називають так: номер будинку й вулиця.")],
 review=True)
